  "roadmap": [
    { "stage": "S1", "title": "Chapter 1 — learn Leonida, do the one missable thing", "hours": "8–12", "trophies": [2, 3, 28, 20, 21], "sources": [1, 2, 3], "text": "Play the story. After the Chapter 1 mission Down to Earth, talk to Lucia in the kitchen in the morning, follow her to the balcony and accept the meditation — the only possibly missable trophy in the game. Keep a manual save at the start of the chapter: there is no mission replay, so save at the start and end of every chapter (15 manual slots, 1 autosave). Cheats switch trophies and saving off, so leave them alone." },
    { "stage": "S2", "title": "Chapter 2 — both leads playable, open the map", "hours": "12–16", "trophies": [4, 8, 24, 46, 54, 55, 16, 33, 34, 47], "sources": [1], "text": "After Coffee Break you can switch between Jason and Lucia and call your partner into free-roam — that unlocks the partner trophies and the both-leads training. Buy garages through the Vice City Real Estate app, register vehicles with Moses, and start Billy's line at Thrillbilly Mudclub." },
    { "stage": "S3", "title": "Chapter 3 — Vice City, heists and side lines", "hours": "14–18", "trophies": [5, 9, 22, 26, 27, 39, 45, 52], "sources": [1], "text": "Vice City opens up: the Cartel Heist, the Key Cloner (Randy's cars, the blue Banshee showroom), Yasmani's jewelry jobs (Snap Gun, fences), and the Dye Pack Jammer for laundering marked bills. Lucia-only Andy and Jason-only Tyrone lines start here." },
    { "stage": "S4", "title": "Chapter 4 — the big jobs", "hours": "14–18", "trophies": [6, 10, 11, 12, 23, 29, 40, 41], "sources": [1], "text": "Child's Play, Headliners and the VCIA Takedown, plus the optional mission That's Where The Money Is… — it unlocks bank vault robberies, which also hand you the armored-truck trophy and the 4-star escape. Finish Kenton's treasure dives and Bret's hunts while you are here." },
    { "stage": "S5", "title": "Chapter 5 & finale — finish the story", "hours": "6–10", "trophies": [7, 13, 50], "sources": [1], "text": "Operation Savage Glory, then the final mission and the gold. After the credits you stay in free-roam and the 100% Completion checklist appears under Progress > Stats > 100% Completion. Nothing on it is missable." },
    { "stage": "S6", "title": "Cleanup — activities, collectibles, strangers", "hours": "40–60", "trophies": [15, 17, 18, 19, 25, 30, 31, 32, 35, 42, 43], "sources": [1], "text": "Stunts (250 of 397), shooting ranges (42 gold medals), drone races (14 locations), 20 race wins, card sets, WAiNK scans, challenges (50 of 80), vehicle discovery, full map unfog, one gang operation per gang, and the 8 stranger strands." },
    { "stage": "S7", "title": "Cleanup — money, profile & 100%", "hours": "40–60", "trophies": [1, 14, 36, 37, 38, 44, 48, 49, 51, 53], "sources": [1, 4], "text": "Finish the 100% checklist (gold), the money trophies, the plane and the tank, the cocktail and the bike kicks, and the 500 criminal-profile actions. Bad Luck, I Guess is still unconfirmed — check the trophy's note before chasing it. The platinum pops when the other 54 are done." }
  ],
